import{_ as i,o as t,c as d,j as e,a as s}from"./chunks/framework.BvHJbMD4.js";const g=JSON.parse('{"title":"Logbuch-Eintrag: Die Sache mit dem Geld und den kleinen Punkten","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/die-sache-mit-dem-geld.md","filePath":"logbuch/die-sache-mit-dem-geld.md"}'),a={name:"logbuch/die-sache-mit-dem-geld.md"};function r(l,n,u,h,c,m){return t(),d("div",null,[...n[0]||(n[0]=[e("h1",{id:"logbuch-eintrag-die-sache-mit-dem-geld-und-den-kleinen-punkten",tabindex:"-1"},[s("Logbuch-Eintrag: Die Sache mit dem Geld und den kleinen Punkten "),e("a",{class:"header-anchor",href:"#logbuch-eintrag-die-sache-mit-dem-geld-und-den-kleinen-punkten","aria-label":'Permalink to "Logbuch-Eintrag: Die Sache mit dem Geld und den kleinen Punkten"'},"​")],-1),e("p",null,`Jetzt pass mal auf. Oder besser gesagt: Lies einfach weiter. Wir sitzen da, du weißt schon, an diesem Horten-Dingsda, dieser Mockumentary, und reden dauernd von "Pointillismus des Geldes". Klingt ja hochtrabend, nicht? Als wär's ein Konzept, das man mit einem Latte Macchiato und einer dieser Designerbrillen diskutiert. Aber die Wahrheit, das sag ich dir, die ist viel banaler. Und gleichzeitig viel gruseliger.`,-1),e("p",null,'Du denkst, Geld ist wie ein Berg, massiv, unüberwindlich. Aber das ist der Fehler. Geld ist nicht wie ein Berg. Geld ist wie lauter kleine Punkte. Wie bei Seurat, nur halt in Scheinen und Überweisungen. Jeder Punkt für sich: harmlos. Eine Kleinigkeit, ein Schmiergeld hier, eine Spende da, ein "Service-Entgelt" dort. Einzeln gesehen: Nix. Ein Nichts. Ein Furz im Wind.',-1),e("p",null,"Aber dann, du Dummkopf, kommt der Clou. All diese Punkte, diese kleinen, unschuldigen Furze, die sammeln sich. Und plötzlich, schwups, hast du kein Nichts mehr. Sondern ein Bild. Ein riesengroßes, scheußliches Bild aus lauter kleinen Nichts. Und auf diesem Bild: da steht dann das Horten-Kaufhaus. Oder das Museum. Oder das ganze verflixte System.",-1),e("p",null,'Die Leute fragen uns: "Wie recherchiert ihr das? Wo sind die Archive, die geheimen Dokumente?" Und ich sage: "Archive? Dokumente? Vergiss es." Wir suchen keine großen, roten Stempel. Wir suchen die Punkte. Die kleinen. Die, wo keiner hinschaut. Den Zettel, der vom Tisch fällt. Das Wort, das im Nebensatz untergeht. Das sind die wahren Sprengsätze. Die kleinen Pointillismus-Punkte.',-1),e("p",null,"Und jetzt komm mir nicht mit Ethik. Oder Moral. Oder wie man das heutzutage nennt. Das ist ein Film. Eine Mockumentary. Wir malen ja nur das Bild, das schon da ist. Punkt für Punkt. Du verstehst? Oder auch nicht. Ist auch wurscht. Hauptsache, es schauen genug Leute hin, wenn wir fertig sind. Und vielleicht, nur vielleicht, sehen sie dann auch die Punkte. All die kleinen, fiesen Punkte.",-1)])])}const k=i(a,[["render",r]]);export{g as __pageData,k as default};
